Local Ltac dj_lia ::=
  first [ let a := dj_subject in progress (dj_reveal_for a); lia
        | lia
        | match goal with K : hideL _ |- _ => unfold hideL in K; lia end ].
Definition kept (P : Prop) : Prop := P.
Lemma kept_intro : forall P : Prop, P -> kept P. Proof. intros P p. exact p. Qed.
Lemma kept_elim : forall P : Prop, kept P -> P. Proof. intros P p. exact p. Qed.
Ltac keep H := apply kept_intro in H.
Ltac unkeep H := apply kept_elim in H.

(* [comment removed for export] *)
Ltac acc_rd8 AC MU WH a M8 RD :=
  lazymatch type of AC with accessible _ ?O ?n =>
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    let ACc := fresh "ACc" in
    assert (ACc : accessible mc O n) by (eapply accessible_transport_hi; [exact AC| exact MU| exact WH]);
    pose proof (accessible_read0_sr mc O n a ACc ltac:(lia) M8 ltac:(lia)) as RD; clear ACc
  end end.

